import{_ as e,C as r,c as t,o as a,j as n,G as o,a0 as l,a as i}from"./chunks/framework.DKRgXLPU.js";const s=JSON.parse('{"title":"Spillerudtalelser","description":"","frontmatter":{},"headers":[],"relativePath":"da/testimonials.md","filePath":"da/testimonials.md"}');const d=e({name:"da/testimonials.md"},[["render",function(e,s,d,k,u,g){const m=r("AdBanner"),p=r("AdInArticle");return a(),t("div",null,[s[0]||(s[0]=n("h1",{id:"spillerudtalelser",tabindex:"-1"},[i("Spillerudtalelser "),n("a",{class:"header-anchor",href:"#spillerudtalelser","aria-label":'Permalink to "Spillerudtalelser"'},"​")],-1)),o(m),s[1]||(s[1]=l('<p>Ægte feedback fra elite-petanquespillere, der har brugt Pétanque Academys ressourcer til at forbedre deres mentale spil og konkurrencepræstationer.</p><div class="tip custom-block"><p class="custom-block-title">Autentisk og anonym</p><p>Disse udtalelser repræsenterer ægte feedback fra spillere på forskellige konkurrenceniveauer. Alle udtalelser er anonyme for at beskytte spillernes privatliv og opfordre til ærlig deling.</p></div><h2 id="regionale-og-nationale-konkurrenter" tabindex="-1">Regionale og nationale konkurrenter <a class="header-anchor" href="#regionale-og-nationale-konkurrenter" aria-label="Permalink to &quot;Regionale og nationale konkurrenter&quot;">​</a></h2><h3 id="quot-den-indre-coachramme-ændrede-alt-quot" tabindex="-1">&quot;Den indre coachramme ændrede alt&quot; <a class="header-anchor" href="#quot-den-indre-coachramme-ændrede-alt-quot" aria-label="Permalink to &quot;&amp;quot;Den indre coachramme ændrede alt&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Jeg har spillet konkurrencer i 12 år, og jeg troede, jeg vidste alt om petanque. Men jeg var min egen værste fjende – jeg kritiserede konstant mig selv efter fejltagelser. Indre træner vs. Indre kritiker-rammen fra Mental styrke-modulet gav mig en helt anden måde at tale til mig selv på under konkurrencer.&quot;</p><p><em>Inden for to måneder bemærkede mine holdkammerater forskellen. Jeg var roligere, kom mig hurtigere over dårlige kast og nød faktisk konkurrencen igen. Jeg blev nummer 3 i regionsstævnet i år – mit bedste resultat nogensinde.</em></p></blockquote><p><strong>— Regionalmester, Frankrig</strong></p><hr><h3 id="quot-endelig-en-der-forstar-eliteudvikling-quot" tabindex="-1">&quot;Endelig en der forstår eliteudvikling&quot; <a class="header-anchor" href="#quot-endelig-en-der-forstar-eliteudvikling-quot" aria-label="Permalink to &quot;&amp;quot;Endelig en der forstår eliteudvikling&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Det meste petanque-træning handler bare om at &#39;øve sig mere&#39; eller &#39;arbejde på sin teknik&#39;. Men når man har spillet i over 15 år, er det ikke problemet. Problemet er at få adgang til sin teknik under pres.&quot;</p><p><em>Zone-modulet forklarede præcis, hvad jeg oplevede – at overtænke under udførelsen, forblive i analytisk tilstand, når jeg havde brug for at være i flow. De praktiske teknikker til at skifte tilstand har været banebrydende.</em></p><p><em>Dette er den første ressource, jeg har fundet, der rent faktisk adresserer det mentale spil på eliteniveau.</em></p></blockquote><p><strong>— Landsholdsspiller, Sverige</strong></p><hr><h3 id="quot-workshop-metoden-transformerede-vores-klub-quot" tabindex="-1">&quot;Workshop-metoden transformerede vores klub&quot; <a class="header-anchor" href="#quot-workshop-metoden-transformerede-vores-klub-quot" aria-label="Permalink to &quot;&amp;quot;Workshop-metoden transformerede vores klub&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Jeg er klubtræner, og jeg brugte workshopguiden til at afholde en mental spilsession med vores top 8 spillere. Den psykologiske sikkerhedsramme og det strukturerede diskussionsformat skabte samtaler, vi aldrig havde haft før.&quot;</p><p><em>Spillerne åbnede op om deres indre kritikere, deres presreaktioner og deres kommunikationsudfordringer i holdet. Det var utroligt stærkt. Vi afholder nu disse sessioner månedligt, og holdkulturen har ændret sig fuldstændigt.</em></p></blockquote><p><strong>— Klubtræner, Tyskland</strong></p>',14)),o(p),s[2]||(s[2]=l('<hr><h2 id="turneringsspillere" tabindex="-1">Turneringsspillere <a class="header-anchor" href="#turneringsspillere" aria-label="Permalink to &quot;Turneringsspillere&quot;">​</a></h2><h3 id="quot-praktiske-værktøjer-der-rent-faktisk-virker-quot" tabindex="-1">&quot;Praktiske værktøjer, der rent faktisk virker&quot; <a class="header-anchor" href="#quot-praktiske-værktøjer-der-rent-faktisk-virker-quot" aria-label="Permalink to &quot;&amp;quot;Praktiske værktøjer, der rent faktisk virker&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Jeg har læst bøger om sportspsykologi før, men de er altid for generelle eller for akademiske. Målskabelonen og Dagbogsskabelonen fra Pétanque Academy var præcis, hvad jeg havde brug for – praktiske, specifikke for pétanque og øjeblikkeligt brugbare.&quot;</p><p><em>Jeg brugte målskabelonen og havde en klar 3-måneders udviklingsplan på 30 minutter. Dagbogsskabelonen hjælper mig med at spore ikke kun resultater, men også mental præstation. Disse værktøjer er guld værd.</em></p></blockquote><p><strong>— Turneringsspiller, Spanien</strong></p><hr><h3 id="quot-mindfulness-teknikkerne-virker-i-konkurrence-quot" tabindex="-1">&quot;Mindfulness-teknikkerne virker i konkurrence&quot; <a class="header-anchor" href="#quot-mindfulness-teknikkerne-virker-i-konkurrence-quot" aria-label="Permalink to &quot;&amp;quot;Mindfulness-teknikkerne virker i konkurrence&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Jeg var skeptisk omkring mindfulness – det virkede for &#39;blødt&#39; til konkurrencesport. Men teknikkerne i Mindfulness-modulet er praktiske og specifikke. 3-åndedrætsnulstillingen, kropsscanningen for spændinger, fokusøvelserne i nuet.&quot;</p><p><em>Jeg træner 10 minutter hver morgen, og jeg kan nu bruge disse teknikker under konkurrencer. Når jeg føler presset vokser, har jeg værktøjer til at håndtere det. Dette har gjort en målbar forskel i min præstation.</em></p></blockquote><p><strong>— Turneringsspiller, Holland</strong></p><hr><h3 id="quot-forstaelse-af-flowtilstande-frigjorde-mit-potentiale-quot" tabindex="-1">&quot;Forståelse af flowtilstande frigjorde mit potentiale&quot; <a class="header-anchor" href="#quot-forstaelse-af-flowtilstande-frigjorde-mit-potentiale-quot" aria-label="Permalink to &quot;&amp;quot;Forståelse af flowtilstande frigjorde mit potentiale&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Jeg havde haft spil, hvor alting klikkede – hvor jeg ikke tænkte, bare spillede perfekt. Men jeg vidste ikke, hvordan jeg skulle få adgang til den tilstand konsekvent. Zone-modulet forklarede videnskaben bag det og gav mig praktiske teknikker.&quot;</p><p><em>At lære om transient hypofrontalitet, forstå skiftet mellem planlægning og udførelse, øve flow-triggere – denne viden har gjort disse peak performance-tilstande meget mere tilgængelige. Jeg spiller min bedste petanque nogensinde.</em></p></blockquote><p><strong>— Regional spiller, Frankrig</strong></p><hr><h2 id="holdspillere" tabindex="-1">Holdspillere <a class="header-anchor" href="#holdspillere" aria-label="Permalink to &quot;Holdspillere&quot;">​</a></h2><h3 id="quot-blev-den-holdkammerat-alle-ønsker-sig-quot" tabindex="-1">&quot;Blev den holdkammerat, alle ønsker sig&quot; <a class="header-anchor" href="#quot-blev-den-holdkammerat-alle-ønsker-sig-quot" aria-label="Permalink to &quot;&amp;quot;Blev den holdkammerat, alle ønsker sig&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Jeg var teknisk stærk, men havde det svært i holdkonkurrencer. Holddynamikmodulet viste mig, at det at være en god holdspiller ikke kun handler om at lave gode kast – det handler om kommunikation, tillid og psykologisk tryghed.&quot;</p><p><em>Jeg lærte at sætte ord på tillid, at kommunikere strategi klart og at støtte holdkammerater efter fejltagelser. Inden for få måneder gik jeg fra at være undgået til at være eftertragtet som partner. Vandt det regionale holdmesterskab i år.</em></p></blockquote><p><strong>— Holdspiller, Italien</strong></p><hr><h3 id="quot-kommunikationsrammen-reddede-vores-partnerskab-quot" tabindex="-1">&quot;Kommunikationsrammen reddede vores partnerskab&quot; <a class="header-anchor" href="#quot-kommunikationsrammen-reddede-vores-partnerskab-quot" aria-label="Permalink to &quot;&amp;quot;Kommunikationsrammen reddede vores partnerskab&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Min faste partner og jeg havde spændinger – forskellige spillestile, dårlig kommunikation og ophobning af frustration. Team Player-modulet gav os en ramme til at diskutere det konstruktivt.&quot;</p><p><em>Vi lærte om kommunikationsmønstre, om at opbygge tillid og om at skabe psykologisk tryghed. Vi havde ærlige samtaler ved hjælp af workshopformatet. Vores partnerskab er stærkere end nogensinde, og vores resultater viser det.</em></p></blockquote><p><strong>— Doubleholdet, Norge</strong></p><hr><h2 id="trænere-og-trænere" tabindex="-1">Trænere og trænere <a class="header-anchor" href="#trænere-og-trænere" aria-label="Permalink to &quot;Trænere og trænere&quot;">​</a></h2><h3 id="quot-sadan-ser-elitetræning-ud-quot" tabindex="-1">&quot;Sådan ser elitetræning ud&quot; <a class="header-anchor" href="#quot-sadan-ser-elitetræning-ud-quot" aria-label="Permalink to &quot;&amp;quot;Sådan ser elitetræning ud&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Jeg har trænet petanque i 20 år, mest med fokus på teknik. Men jeg så spillere med fremragende teknik fejle under pres. Uddannelsesmodulerne gav mig rammerne til at håndtere det mentale spil systematisk.&quot;</p><p><em>Træningslejrguiden hjalp mig med at strukturere et weekendprogram, der kombinerede teknisk arbejde med mental spiltræning. Feedbacken fra spillerne var utrolig – de sagde, at det var den mest værdifulde træning, de nogensinde havde deltaget i.</em></p></blockquote><p><strong>— Træner, Frankrig</strong></p><hr><h3 id="quot-evidensbaseret-tilgang-til-mental-træning-quot" tabindex="-1">&quot;Evidensbaseret tilgang til mental træning&quot; <a class="header-anchor" href="#quot-evidensbaseret-tilgang-til-mental-træning-quot" aria-label="Permalink to &quot;&amp;quot;Evidensbaseret tilgang til mental træning&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Det jeg sætter mest pris på er, at dette ikke bare er motivationsvrøvl. Indholdet er baseret på faktisk psykologisk forskning – flowtilstandsvidenskab, mindfulness-studier og præstationspsykologi. Men det er omsat til praktiske, brugbare teknikker.&quot;</p><p><em>Jeg bruger disse moduler som fundament for mental spilcoaching med mine elitespillere. Den strukturerede tilgang, de klare rammer, de praktiske øvelser – dette er indhold på professionelt niveau.</em></p></blockquote><p><strong>— Sportspsykolog og petanquetræner, Storbritannien</strong></p>',31)),o(m),s[3]||(s[3]=l('<hr><h2 id="fælles-temaer" tabindex="-1">Fælles temaer <a class="header-anchor" href="#fælles-temaer" aria-label="Permalink to &quot;Fælles temaer&quot;">​</a></h2><h3 id="hvad-spillerne-værdsætter-mest" tabindex="-1">Hvad spillerne værdsætter mest <a class="header-anchor" href="#hvad-spillerne-værdsætter-mest" aria-label="Permalink to &quot;Hvad spillerne værdsætter mest&quot;">​</a></h3><p>Baseret på feedback fremhæver spillerne konsekvent:</p><ol><li><strong>Praktisk, handlingsrettet indhold</strong> - Ikke teori, men teknikker du kan bruge i dag</li><li><strong>Pétanque-specifik</strong> - Designet til de unikke udfordringer ved petanque</li><li><strong>Fokus på eliteniveau</strong> - Fokuserer på det mentale spil, ikke på den grundlæggende teknik</li><li><strong>Strukturerede rammer</strong> - Klare systemer, ikke vage råd</li><li><strong>Gratis og tilgængelig</strong> - Ingen betalingsmure, tilgængelig for alle</li></ol><h3 id="malbare-resultater" tabindex="-1">Målbare resultater <a class="header-anchor" href="#malbare-resultater" aria-label="Permalink to &quot;Målbare resultater&quot;">​</a></h3><p>Spillere rapporterer forbedringer i:</p><ul><li>Konkurrencepræstation og resultater</li><li>Konsistens under pres</li><li>Restitutionstid efter fejl</li><li>Teamkommunikation og dynamik</li><li>Glæde ved konkurrence</li><li>Mental modstandsdygtighed</li></ul><h2 id="del-din-oplevelse" tabindex="-1">Del din oplevelse <a class="header-anchor" href="#del-din-oplevelse" aria-label="Permalink to &quot;Del din oplevelse&quot;">​</a></h2><p>Har du brugt Pétanque Academys ressourcer? Vi vil meget gerne høre om din oplevelse.</p><p><strong>Send din anbefaling via e-mail til:</strong> <a href="mailto:patrik.wiik@gmail.com?subject=Anbefaling" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Omfatte:</strong></p><ul><li>Dit erfaringsniveau</li><li>Hvilke ressourcer du brugte</li><li>Hvilken indflydelse de havde</li><li>Om vi må dele din feedback (navn valgfrit)</li></ul><p>Din historie kan hjælpe andre spillere med at opdage disse ressourcer.</p><hr><h2 id="kom-i-gang" tabindex="-1">Kom i gang <a class="header-anchor" href="#kom-i-gang" aria-label="Permalink to &quot;Kom i gang&quot;">​</a></h2><p>Klar til at udvikle dit mentale spil?</p><div class="tip custom-block"><p class="custom-block-title">Start her</p><ul><li><strong>Nybegynder med mental træning?</strong> → <a href="/da/uddannelse/the-zone/">The Zone</a></li><li><strong>Kæmper du med pres?</strong> → <a href="/da/uddannelse/mental-styrke/">Mental styrke</a></li><li><strong>Holdudfordringer?</strong> → <a href="/da/uddannelse/holdspiller/">Holddynamik</a></li><li><strong>Ønsker du struktur?</strong> → <a href="/da/målskabelon">Målskabelon</a></li></ul></div>',18)),o(m)])}]]);export{s as __pageData,d as default};
